@step(1)
def test_a_bare_string_is_never_split_into_characters():
    try:
        result = cache.normalize_params(DECLARED, {"tickers": "AAPL"})
    except ValueError:
        return
    assert result == cache.normalize_params(DECLARED, {"tickers": ["AAPL"]})


